import numpy as np
import matplotlib.pyplot as plt
import scipy.integrate as integrate

N_0 = 1e4
lambd = 1
D = np.arange(0.1,20,0.0001)

n_D_i3 = np.zeros(len(D))
n_D_i0 = np.zeros(len(D))
n_D_im3 = np.zeros(len(D))

    
for k in range(len(D)):
    n_D_i3[k] = N_0*D[k]**3*np.exp(-lambd*D[k])
    n_D_i0[k] = N_0*D[k]**0*np.exp(-lambd*D[k])
    n_D_im3[k] = N_0*D[k]**(-3)*np.exp(-lambd*D[k])

f,ax = plt.subplots(1,3,figsize=(12,4))
ax[0].grid()
ax[1].grid()
ax[2].grid()
ax[0].plot(D,n_D_i3)
ax[1].plot(D,n_D_i0)
ax[2].plot(D,n_D_im3)
ax[0].set_yscale('log')
ax[1].set_yscale('log')
ax[2].set_yscale('log')
ax[0].set_ylim(1e-1,1e5)
ax[1].set_ylim(1e-5,1e5)
ax[2].set_ylim(1e-9,1e8)
ax[0].set_ylabel('n(D) $m^{-3}$$mm^{-1}$',fontsize=12)
ax[0].set_title('i = 3',fontsize=13)
ax[1].set_title('i = 0',fontsize=13)
ax[2].set_title('i = -3',fontsize=13)
ax[0].set_xlabel('Diameter [mm]',fontsize=13)
ax[1].set_xlabel('Diameter [mm]',fontsize=13)
ax[2].set_xlabel('Diameter [mm]',fontsize=13)
f.suptitle('Gamma distribution n(D) when i = −3, 0, and 3',fontsize=16)
plt.savefig('gamma distribution.png', dpi=300)

f1 = lambda D :  1e4*D**(6+3)*np.exp(-D)
f2 = lambda D :  1e4*D**(6+0)*np.exp(-D)
f3 = lambda D :  1e4*D**(6-3)*np.exp(-D)
z_3 = integrate.quad(f1, 0.1, 20)
z_0 = integrate.quad(f2, 0.1, 20)
z_m3 = integrate.quad(f3, 0.1, 20)
print('radar reflectivity factor and its error for i=3 is ',10*np.log10(z_3[0]))
print('radar reflectivity factor and its error for i=0 is ',10*np.log10(z_0[0]))
print('radar reflectivity factor and its error for i=-3 is ',10*np.log10(z_m3[0]))

